const css = code;
if (!/\.shell\s*{[^}]*display\s*:\s*grid/i.test(css)) throw new Error("The shell must be a grid.");
if (!/\.shell\s*{[^}]*grid-template-areas\s*:[^;}]*head\s+head/i.test(css)) throw new Error("Rows start with \"head head\".");
if (!/\.shell\s*{[^}]*grid-template-areas\s*:[^;}]*side\s+main/i.test(css)) throw new Error("Middle row: \"side main\".");
if (!/\.shell\s*{[^}]*grid-template-areas\s*:[^;}]*side\s+foot/i.test(css)) throw new Error("Bottom row: \"side foot\".");
if (!/\.shell\s*{[^}]*grid-template-columns\s*:[^;}]*220px/i.test(css)) throw new Error("Sidebar column fixed at 220px.");
if (!/\.shell\s*{[^}]*grid-template-columns\s*:[^;}]*1fr/i.test(css)) throw new Error("Main column takes the rest (1fr).");
